package archtest

// INVARIANT: REQUIRED-DEP-NIL-GUARD-01
//
// required_dep_nil_guard_test.go — Hard funnel for Service.validateRequired
// generated by tools/codegen/requireddepsgen.
//
// Single source = Service struct field gocell:"required" tag.
// Derived       = service_required_gen.go::validateRequired().
// Callsite      = NewXxx calls validateRequired() post-options, exactly once.
// Downstream ban = service.go may NOT contain hand-written validation.IsNilInterface.
//
// Rules:
//   A1 [TestRequiredDepNilGuard_A1_GeneratorOutputGroundTruth]
//      service_required_gen.go must be byte-identical to the generator output
//      for its sibling service.go (regenerate-and-diff Hard lock). Hand-edits,
//      drift, and stale files are all rejected at byte granularity.
//   A2 [TestRequiredDepNilGuard_A2_CallsiteUniqueness]
//      In a file whose Service struct has a gocell:"required" field, every
//      New*-returning-*Service constructor must (a) return error as its last
//      result, and (b) call validateRequired() exactly once, after the options
//      loop, consuming the error in the canonical form
//      `if err := s.validateRequired(); err != nil { return ..., err }`.
//      A discarded result, a bare expression statement, or a bare-*Service
//      signature that cannot propagate the error is flagged (cf. fx/dig: a
//      construction error must abort construction, not merely be observed).
//   A3 [TestRequiredDepNilGuard_A3_HandwrittenIsNilInterfaceBan]
//      service.go (non-gen files) must not call validation.IsNilInterface on a
//      gocell:"required" field. Calls on optional-dep option params (builder-
//      noop typed-nil pattern, e.g. WithMetrics) are allowed (scoping mirrors B2).
//   A4 [TestRequiredDepNilGuard_A4_TagValueWhitelist]
//      gocell struct tag values must be in {"", "required"}.
//
// Blind spots (A2+A3 scan coverage gaps; each has a reverse self-test):
//
//   B1 [TestRequiredDepNilGuard_BlindSpot_B1_NoReflectNilCheck]
//      reflect.ValueOf(s.X).IsNil() on a required field bypasses A3.
//   B2 [TestRequiredDepNilGuard_BlindSpot_B2_NoDirectNilCompare]
//      Any FuncDecl body compares `<recv>.X` to nil where X is a
//      gocell:"required"-tagged field on this file's Service struct.
//      Generated *_gen.go files allowlisted. Optional / feature-gate fields
//      (e.g. sessionStore in sessionvalidate per its godoc) are not in scope
//      since they carry no `gocell:"required"` tag.
//   B3 [TestRequiredDepNilGuard_BlindSpot_B3_NoIndirectIsNilInterfaceRef]
//      Function-value / pointer / method-value references to IsNilInterface
//      bypass the callsite-form check in A3.
//   B5 [TestRequiredDepNilGuard_BlindSpot_B5_NoValidateRequiredMethodValueLeak]
//      validateRequired used as a method value (s.validateRequired) outside
//      direct call position bypasses A2 counting.
//
// (There is no external-nil-guard-helper rule: A2 forces validateRequired() to
// run at construction regardless, so an external wrapper cannot bypass the
// funnel — it would only be a redundant parallel check, not a defeat.)

import (
	"bytes"
	"errors"
	"fmt"
	"go/ast"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/ghbvf/gocell/tools/codegen/requireddepsgen"
)

// fixtureBuildTag — the canonical unexported const declared in fixture.go — is
// emitted into fixture service_required_gen.go files so they compile only under
// //go:build archtest_fixture. A1 fixture comparison runs the generator with
// this tag; production A1 uses the empty tag. (#944 consolidated the former
// file-local const here onto the package single source.)

// --- A1: Generator Ground Truth ---

// TestRequiredDepNilGuard_A1_GeneratorOutputGroundTruth verifies that every
// service_required_gen.go file is byte-identical to the generator output for
// its sibling service.go. This is the upstream Hard lock of the funnel: any
// hand-edit, drift, or stale file is rejected at byte granularity.
//
// Fixture sub-tests run the generator with BuildTag="archtest_fixture" to
// match the //go:build header in fixture gen files; production uses the empty
// BuildTag.
func TestRequiredDepNilGuard_A1_GeneratorOutputGroundTruth(t *testing.T) {
	for _, fix := range []string{"green_basic", "red_stale_generator"} {
		fix := fix
		t.Run("fixture_"+fix, func(t *testing.T) {
			root := findModuleRoot(t)
			fixtureDir := filepath.Join(root, "tools", "archtest", "testdata",
				"required_dep_nil_guard_fixtures", fix)
			diags := runA1Check(t, root, fixtureDir, fixtureBuildTag)
			goldenPath := filepath.Join(fixtureDir, "diag.golden")
			AssertGolden(t, goldenPath, diags)
		})
	}

	t.Run("production_scan", func(t *testing.T) {
		root := findModuleRoot(t)
		slicePaths := discoverSlicePaths(t, root)
		var allDiags []Diagnostic
		for _, sp := range slicePaths {
			allDiags = append(allDiags, runA1Check(t, root, sp, "")...)
		}
		Report(t, requiredDepNilGuardRule+"-A1", allDiags)
	})
}

// runA1Check regenerates the gen file in-memory and diffs against the committed
// file byte-for-byte. buildTag is passed through to the generator and must
// match the build tag header used by the target gen file (empty for production,
// "archtest_fixture" for fixtures).
func runA1Check(t *testing.T, modRoot, sliceDir, buildTag string) []Diagnostic {
	t.Helper()
	svcFile := filepath.Join(sliceDir, "service.go")
	genFile := filepath.Join(sliceDir, "service_required_gen.go")

	// Skip slices without a service.go (defensive; production discovery already filters).
	if _, err := os.Stat(svcFile); err != nil {
		return nil
	}

	want, err := requireddepsgen.GenerateWithOpts(sliceDir, requireddepsgen.Opts{BuildTag: buildTag})
	if err != nil {
		// ErrNoServiceStruct is not a violation: type-alias service.go files and
		// pure-delegate packages legitimately have no Service struct declaration.
		// They neither need nor should have a service_required_gen.go.
		if errors.Is(err, requireddepsgen.ErrNoServiceStruct) {
			return nil
		}
		rel := requiredDepSlashRel(modRoot, svcFile)
		return []Diagnostic{{
			Rel:     rel,
			Line:    1,
			Message: fmt.Sprintf("REQUIRED-DEP-NIL-GUARD-01-A1: generator failed: %v (%s)", err, requiredDepNilGuardRule),
		}}
	}

	// Generator returns nil when the Service struct has no required fields
	// and the file should not exist; treat that as "no expected output".
	noRequired := len(want) == 0

	got, err := os.ReadFile(genFile) //nolint:gosec // path is test-derived
	switch {
	case noRequired && err != nil:
		// Expected: no required fields, no gen file. PASS.
		return nil
	case noRequired && err == nil:
		rel := requiredDepSlashRel(modRoot, genFile)
		return []Diagnostic{{
			Rel:  rel,
			Line: 1,
			Message: fmt.Sprintf(
				"REQUIRED-DEP-NIL-GUARD-01-A1: service_required_gen.go exists but service.go has "+
					"no required fields; delete the gen file (%s)",
				requiredDepNilGuardRule,
			),
		}}
	case err != nil:
		rel := requiredDepSlashRel(modRoot, svcFile)
		return []Diagnostic{{
			Rel:  rel,
			Line: 1,
			Message: fmt.Sprintf(
				"REQUIRED-DEP-NIL-GUARD-01-A1: service_required_gen.go missing; "+
					"run gocell generate required-deps --all (%s)",
				requiredDepNilGuardRule,
			),
		}}
	}

	if !bytes.Equal(want, got) {
		rel := requiredDepSlashRel(modRoot, genFile)
		return []Diagnostic{{
			Rel:  rel,
			Line: 1,
			Message: fmt.Sprintf(
				"REQUIRED-DEP-NIL-GUARD-01-A1: service_required_gen.go drift from generator output; "+
					"hand-edits forbidden, run gocell generate required-deps --all (%s)",
				requiredDepNilGuardRule,
			),
		}}
	}
	return nil
}

// discoverSlicePaths returns every slice directory with a service.go that the
// generator would emit a gen file for.
func discoverSlicePaths(t *testing.T, modRoot string) []string {
	t.Helper()
	paths, err := requireddepsgen.FindSlicePaths(modRoot)
	require.NoError(t, err, "FindSlicePaths")
	return paths
}

// requiredDepSlashRel returns the module-relative slash path for absPath.
func requiredDepSlashRel(modRoot, absPath string) string {
	rel, err := filepath.Rel(modRoot, absPath)
	if err != nil {
		return absPath
	}
	return filepath.ToSlash(rel)
}

// --- A2: Callsite Uniqueness ---

// TestRequiredDepNilGuard_A2_CallsiteUniqueness verifies that every
// NewXxx(*Service, error) function calls validateRequired() exactly once,
// after any options loop.
func TestRequiredDepNilGuard_A2_CallsiteUniqueness(t *testing.T) {
	for _, fix := range []string{
		"green_basic",
		"red_missing_callsite",
		"red_pre_options_callsite",
		"red_unconsumed_callsite",
		"red_bare_service_return",
	} {
		fix := fix
		t.Run("fixture_"+fix, func(t *testing.T) {
			root := findModuleRoot(t)
			fixtureDir := filepath.Join(root, "tools", "archtest", "testdata",
				"required_dep_nil_guard_fixtures", fix)
			pattern := "./tools/archtest/testdata/required_dep_nil_guard_fixtures/" + fix
			diags := Run(t, Fixture(FixtureOpts{}, []string{pattern}), func(p *Pass) []Diagnostic {
				if p.TypesInfo == nil {
					return nil
				}
				var out []Diagnostic
				for _, file := range p.Files {
					out = append(out, scanA2(p, file)...)
				}
				return out
			})

			goldenPath := filepath.Join(fixtureDir, "diag.golden")
			AssertGolden(t, goldenPath, diags)
		})
	}

	t.Run("production_scan", func(t *testing.T) {
		Report(t, requiredDepNilGuardRule+"-A2", CheckRequiredDepNilGuardA2(t, ConfigForExternalCell{}))
	})
}

// --- A3: Hand-written IsNilInterface Ban ---

// TestRequiredDepNilGuard_A3_HandwrittenIsNilInterfaceBan verifies that no
// hand-written service.go calls validation.IsNilInterface to guard a REQUIRED
// field.
func TestRequiredDepNilGuard_A3_HandwrittenIsNilInterfaceBan(t *testing.T) {
	for _, fix := range []string{"green_basic", "green_optional_isnil", "red_handwritten_guard"} {
		fix := fix
		t.Run("fixture_"+fix, func(t *testing.T) {
			root := findModuleRoot(t)
			fixtureDir := filepath.Join(root, "tools", "archtest", "testdata",
				"required_dep_nil_guard_fixtures", fix)
			pattern := "./tools/archtest/testdata/required_dep_nil_guard_fixtures/" + fix
			diags := Run(t, Fixture(FixtureOpts{}, []string{pattern}), func(p *Pass) []Diagnostic {
				if p.TypesInfo == nil {
					return nil
				}
				var out []Diagnostic
				for _, file := range p.Files {
					rel := p.Rel(file)

					if strings.HasSuffix(rel, "_gen.go") {
						continue
					}
					out = append(out, scanA3(p, file)...)
				}
				return out
			})

			goldenPath := filepath.Join(fixtureDir, "diag.golden")
			AssertGolden(t, goldenPath, diags)
		})
	}

	t.Run("production_scan", func(t *testing.T) {
		Report(t, requiredDepNilGuardRule+"-A3", CheckRequiredDepNilGuardA3(t, ConfigForExternalCell{}))
	})
}

