// --- B1: No reflect nil check on required field ---

// TestRequiredDepNilGuard_BlindSpot_B1_NoReflectNilCheck is the reverse
// self-test for B1: asserts production code does not use reflect.ValueOf(s.X).IsNil()
// on fields of Service structs.
func TestRequiredDepNilGuard_BlindSpot_B1_NoReflectNilCheck(t *testing.T) {
	root := findModuleRoot(t)
	scope := ModuleScope(root)
	diags := Run(t, AST(scope), func(p *Pass) []Diagnostic {
		var out []Diagnostic
		for _, file := range p.Files {
			rel := p.Rel(file)
			if !isHandWrittenServiceFile(rel) {
				continue
			}
			out = append(out, scanB1ReflectNilCheck(p, file)...)
		}
		return out
	})

	assert.Empty(t, diags,
		"B1 blind-spot: reflect.ValueOf(s.X).IsNil() on Service fields bypasses A3; use generated validateRequired() instead")
}

// scanB1ReflectNilCheck detects reflect.ValueOf(x).IsNil() call chains.
func scanB1ReflectNilCheck(p *Pass, file *ast.File) []Diagnostic {
	var out []Diagnostic
	EachInSubtree[ast.CallExpr](file, func(call *ast.CallExpr) {
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "IsNil" {
			return
		}
		inner, ok := sel.X.(*ast.CallExpr)
		if !ok {
			return
		}
		innerSel, ok := inner.Fun.(*ast.SelectorExpr)
		if !ok || innerSel.Sel.Name != "ValueOf" {
			return
		}
		xIdent, ok := innerSel.X.(*ast.Ident)
		if !ok || xIdent.Name != "reflect" {
			return
		}
		out = append(out, Diagnostic{
			Rel:     p.Rel(file),
			Line:    p.Fset.Position(call.Pos()).Line,
			Message: "B1: reflect.ValueOf(s.X).IsNil() in service.go bypasses generated validateRequired() funnel",
		})
	})
	return out
}

// --- B2: No direct nil compare on required fields ---

// TestRequiredDepNilGuard_BlindSpot_B2_NoDirectNilCompare is the reverse
// self-test for B2: asserts that no FuncDecl body in a hand-written service.go
// contains `<recv>.X == nil` or `<recv>.X != nil` where X is a Service struct
// field tagged gocell:"required".
func TestRequiredDepNilGuard_BlindSpot_B2_NoDirectNilCompare(t *testing.T) {
	for _, fix := range []string{"green_basic", "red_handwritten_guard", "red_direct_nil_compare"} {
		fix := fix
		t.Run("fixture_"+fix, func(t *testing.T) {
			root := findModuleRoot(t)
			fixtureDir := filepath.Join(root, "tools", "archtest", "testdata",
				"required_dep_nil_guard_fixtures", fix)
			pattern := "./tools/archtest/testdata/required_dep_nil_guard_fixtures/" + fix
			diags := Run(t, Fixture(FixtureOpts{}, []string{pattern}), func(p *Pass) []Diagnostic {
				var out []Diagnostic
				for _, file := range p.Files {
					rel := p.Rel(file)

					if strings.HasSuffix(rel, "_gen.go") {
						continue
					}
					out = append(out, scanB2RequiredFieldNilCompare(p, file)...)
				}
				return out
			})

			goldenPath := filepath.Join(fixtureDir, "b2.golden")
			AssertGolden(t, goldenPath, diags)
		})
	}

	t.Run("production_scan", func(t *testing.T) {
		root := findModuleRoot(t)
		scope := ModuleScope(root)
		diags := Run(t, AST(scope), func(p *Pass) []Diagnostic {
			var out []Diagnostic
			for _, file := range p.Files {
				rel := p.Rel(file)
				if !isB2InScopeFile(rel) {
					continue
				}
				out = append(out, scanB2RequiredFieldNilCompare(p, file)...)
			}
			return out
		})

		assert.Empty(t, diags,
			"B2 blind-spot: method body compares a gocell:\"required\" field to nil; "+
				"these checks belong in generated validateRequired(), not hand-written method bodies")
	})
}

// isB2InScopeFile reports whether rel is a hand-written service.go in a slice/internal
// directory.
func isB2InScopeFile(rel string) bool {
	return isHandWrittenServiceFile(rel)
}

// scanB2RequiredFieldNilCompare walks all FuncDecl bodies in file, finds
// BinaryExpr of the form `<expr>.<field> == nil` (or !=), and reports those
// where <field> is a gocell:"required"-tagged field on the file's Service struct.
func scanB2RequiredFieldNilCompare(p *Pass, file *ast.File) []Diagnostic {
	requiredFields := requiredFieldNames(file)
	if len(requiredFields) == 0 {
		return nil
	}
	var out []Diagnostic
	EachInChildren[ast.FuncDecl](file, func(fn *ast.FuncDecl) {
		if fn.Body == nil {
			return
		}
		EachInSubtree[ast.BinaryExpr](fn.Body, func(be *ast.BinaryExpr) {
			op := be.Op.String()
			if op != "==" && op != "!=" {
				return
			}
			field := selectorFieldComparedToNil(be)
			if field == "" {
				return
			}
			if !requiredFields[field] {
				return
			}
			out = append(out, Diagnostic{
				Rel:  p.Rel(file),
				Line: p.Fset.Position(be.Pos()).Line,
				Message: fmt.Sprintf(
					"B2: comparison `%s` on required field bypasses generated validateRequired() funnel "+
						"(field is tagged gocell:\"required\"; move guard into the generated method)",
					formatNilCompare(be),
				),
			})
		})
	})
	return out
}

// --- B3: No indirect IsNilInterface reference ---

// TestRequiredDepNilGuard_BlindSpot_B3_NoIndirectIsNilInterfaceRef verifies
// that every reference to validation.IsNilInterface in the module appears in
// direct call position (CallExpr.Fun), not as a function value / pointer.
func TestRequiredDepNilGuard_BlindSpot_B3_NoIndirectIsNilInterfaceRef(t *testing.T) {
	seen := make(map[string]struct{})
	var violations []Diagnostic

	scan := func(p *Pass) []Diagnostic {
		if p.TypesInfo == nil {
			return nil
		}
		for _, file := range p.Files {
			rel := p.Rel(file)
			if strings.HasPrefix(rel, "tools/archtest/testdata/") {
				continue
			}
			violations = append(violations, scanB3IndirectRef(p, file, rel, seen)...)
		}
		return nil
	}
	_ = Run(t, Typed(TypedOpts{}, []string{"./..."}), scan)
	_ = Run(t, Typed(TypedOpts{Tags: FlatNonDefaultTags()}, []string{"./..."}), scan)

	sort.Slice(violations, func(i, j int) bool {
		if violations[i].Rel != violations[j].Rel {
			return violations[i].Rel < violations[j].Rel
		}
		return violations[i].Line < violations[j].Line
	})
	assert.Empty(t, violations,
		"B3: validation.IsNilInterface must only appear in direct call position; "+
			"indirect references bypass A3 form-uniqueness check")
}

// scanB3IndirectRef finds non-call-position references to IsNilInterface.
func scanB3IndirectRef(p *Pass, file *ast.File, rel string, seen map[string]struct{}) []Diagnostic {
	var out []Diagnostic
	legalCallFun := make(map[*ast.Ident]struct{})
	EachInSubtree[ast.CallExpr](file, func(call *ast.CallExpr) {
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok || sel.Sel == nil {
			return
		}
		if isIsNilInterfaceIdentObj(p.TypesInfo.Uses[sel.Sel]) {
			legalCallFun[sel.Sel] = struct{}{}
		}
	})
	for ident, obj := range p.TypesInfo.Uses {
		if !isIsNilInterfaceIdentObj(obj) {
			continue
		}
		identFile := p.Fset.Position(ident.Pos()).Filename
		if identFile != p.Abs(file) {
			continue
		}
		if _, ok := legalCallFun[ident]; ok {
			continue
		}
		if strings.HasSuffix(rel, "_gen.go") {
			continue
		}
		key := fmt.Sprintf("%s:%d", rel, p.Fset.Position(ident.Pos()).Line)
		if _, dup := seen[key]; dup {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, Diagnostic{
			Rel:     rel,
			Line:    p.Fset.Position(ident.Pos()).Line,
			Message: "B3: indirect reference to validation.IsNilInterface; only direct call is permitted",
		})
	}
	return out
}

// --- B5: No validateRequired method value leak ---

// TestRequiredDepNilGuard_BlindSpot_B5_NoValidateRequiredMethodValueLeak
// verifies that validateRequired is only referenced in direct call position.
func TestRequiredDepNilGuard_BlindSpot_B5_NoValidateRequiredMethodValueLeak(t *testing.T) {
	seen := make(map[string]struct{})
	var violations []Diagnostic

	scan := func(p *Pass) []Diagnostic {
		if p.TypesInfo == nil {
			return nil
		}
		for _, file := range p.Files {
			rel := p.Rel(file)
			if strings.HasPrefix(rel, "tools/") ||
				strings.HasPrefix(rel, "generated/") {
				continue
			}
			violations = append(violations, scanB5MethodValueLeak(p, file, rel, seen)...)
		}
		return nil
	}
	_ = Run(t, Typed(TypedOpts{}, []string{"./..."}), scan)
	_ = Run(t, Typed(TypedOpts{Tags: FlatNonDefaultTags()}, []string{"./..."}), scan)

	sort.Slice(violations, func(i, j int) bool {
		if violations[i].Rel != violations[j].Rel {
			return violations[i].Rel < violations[j].Rel
		}
		return violations[i].Line < violations[j].Line
	})
	assert.Empty(t, violations,
		"B5: validateRequired must only appear in direct call (s.validateRequired()); "+
			"method-value usage bypasses A2 counting")
}

// scanB5MethodValueLeak finds validateRequired Sel references not in call position.
func scanB5MethodValueLeak(p *Pass, file *ast.File, rel string, seen map[string]struct{}) []Diagnostic {
	var out []Diagnostic
	legalCalls := make(map[*ast.Ident]struct{})
	EachInSubtree[ast.CallExpr](file, func(call *ast.CallExpr) {
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if ok && sel.Sel != nil && sel.Sel.Name == "validateRequired" {
			legalCalls[sel.Sel] = struct{}{}
		}
	})
	EachInSubtree[ast.SelectorExpr](file, func(sel *ast.SelectorExpr) {
		if sel.Sel == nil || sel.Sel.Name != "validateRequired" {
			return
		}
		if _, ok := legalCalls[sel.Sel]; ok {
			return
		}
		key := fmt.Sprintf("%s:%d", rel, p.Fset.Position(sel.Sel.Pos()).Line)
		if _, dup := seen[key]; dup {
			return
		}
		seen[key] = struct{}{}
		out = append(out, Diagnostic{
			Rel:     rel,
			Line:    p.Fset.Position(sel.Sel.Pos()).Line,
			Message: "B5: validateRequired used as method value (not direct call); bypasses A2 count check",
		})
	})
	return out
}
